document.addEventListener("DOMContentLoaded",function(){const e=document.querySelector(".scr-drop");if(e){const t=e.querySelector('input[type="file"]'),n=e.querySelector(".scr-drop-name");t.addEventListener("change",function(){const c=t.files.length>0;n.textContent=c?t.files[0].name:n.dataset.empty,e.classList.toggle("has-file",c)}),["dragenter","dragover"].forEach(function(t){e.addEventListener(t,function(){e.classList.add("is-over")})}),["dragleave","drop"].forEach(function(t){e.addEventListener(t,function(){e.classList.remove("is-over")})})}const t=document.getElementById("scr-all");t&&t.addEventListener("change",function(){document.querySelectorAll(".scr-check").forEach(function(e){e.checked=t.checked})}),document.querySelectorAll("[data-confirm]").forEach(function(e){e.addEventListener("click",function(t){confirm(e.dataset.confirm)||t.preventDefault()})})});